-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the mbal capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: some graded figure(s) printed; section 3 pick B (strip)
-- advanced: some graded figure(s) printed; section 3 pick B (strip)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update takes them out
--   of the lessons and panels.
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- mbal / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'mbal' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book mbal refused: mbal/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'd97798a4c92de4bab4c50aab77bf8def' and fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb then 'old'
              when md5(prompt) = 'a2b66f64989dd5f799aea0c2173f067c' and fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'mbal' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book mbal refused: mbal/beginner matches neither its published form (prompt md5 d97798a4c92de4bab4c50aab77bf8def) nor its W1 form (prompt md5 a2b66f64989dd5f799aea0c2173f067c), with the fields this file was generated against';
  end if;

  -- mbal / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'mbal' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book mbal refused: mbal/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '17afd148a2efd39c8e142884e008a340' and fields = '[{"key": "wei_bbl", "tol": 500000, "unit": "bbl", "label": "Fetkovich Wei for Ahmed 10-10", "expected": 211934253.721285}, {"key": "j_bbl_d_psi", "tol": 0.5, "unit": "bbl/d/psi", "label": "Aquifer productivity index J", "expected": 116.496154838747}, {"key": "decay_365", "tol": 0.002, "unit": "-", "label": "Decay term over one 365 day step", "expected": 0.422897624804177}, {"key": "we_final_mmbbl", "tol": 0.4, "unit": "MMbbl", "label": "Cumulative We after four steps", "expected": 37.9731544101719}, {"key": "pot_ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP when a pot aquifer is forced on Ekene", "expected": -516449.043355256}, {"key": "pot_r2", "tol": 0.0001, "unit": "-", "label": "R-squared of that wrong-model fit", "expected": 0.999485673716372}]'::jsonb then 'old'
              when md5(prompt) = '18a6332ea1f24ba62671247be2020252' and fields = '[{"key": "wei_bbl", "tol": 500000, "unit": "bbl", "label": "Fetkovich Wei for Ahmed 10-10", "expected": 211934253.721285}, {"key": "j_bbl_d_psi", "tol": 0.5, "unit": "bbl/d/psi", "label": "Aquifer productivity index J", "expected": 116.496154838747}, {"key": "decay_365", "tol": 0.002, "unit": "-", "label": "Decay term over one 365 day step", "expected": 0.422897624804177}, {"key": "we_final_mmbbl", "tol": 0.4, "unit": "MMbbl", "label": "Cumulative We after four steps", "expected": 37.9731544101719}, {"key": "pot_ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP when a pot aquifer is forced on Ekene", "expected": -516449.043355256}, {"key": "pot_r2", "tol": 0.0001, "unit": "-", "label": "R-squared of that wrong-model fit", "expected": 0.999485673716372}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'mbal' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book mbal refused: mbal/intermediate matches neither its published form (prompt md5 17afd148a2efd39c8e142884e008a340) nor its W1 form (prompt md5 18a6332ea1f24ba62671247be2020252), with the fields this file was generated against';
  end if;

  -- mbal / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'mbal' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book mbal refused: mbal/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '4a6a40d31bb365b41a1667497b8a0a8e' and fields = '[{"key": "dake_ooip_mmstb", "tol": 3, "unit": "MMSTB", "label": "Dake 9.2 OOIP from Carter-Tracy", "expected": 307.221409553720}, {"key": "dake_we_mmrb", "tol": 1, "unit": "MMrb", "label": "Dake 9.2 cumulative water influx", "expected": 88.0645883139400}, {"key": "pd_finite_100", "tol": 0.05, "unit": "-", "label": "Bounded-circle pD at reD 5, tD 100", "expected": 9.30886079703705}, {"key": "a111_we_bbl", "tol": 500, "unit": "bbl", "label": "Ahmed 11-1 water influx We", "expected": 411281.250000001}, {"key": "a111_wdi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 water drive index", "expected": 0.211250877090399}, {"key": "a111_ddi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 depletion drive index, net convention", "expected": 0.43854519939188374}]'::jsonb then 'old'
              when md5(prompt) = 'fd372e1e2039a84d12c0de1b730f149f' and fields = '[{"key": "dake_ooip_mmstb", "tol": 3, "unit": "MMSTB", "label": "Dake 9.2 OOIP from Carter-Tracy", "expected": 307.221409553720}, {"key": "dake_we_mmrb", "tol": 1, "unit": "MMrb", "label": "Dake 9.2 cumulative water influx", "expected": 88.0645883139400}, {"key": "pd_finite_100", "tol": 0.05, "unit": "-", "label": "Bounded-circle pD at reD 5, tD 100", "expected": 9.30886079703705}, {"key": "a111_we_bbl", "tol": 500, "unit": "bbl", "label": "Ahmed 11-1 water influx We", "expected": 411281.250000001}, {"key": "a111_wdi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 water drive index", "expected": 0.211250877090399}, {"key": "a111_ddi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 depletion drive index, net convention", "expected": 0.43854519939188374}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'mbal' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book mbal refused: mbal/advanced matches neither its published form (prompt md5 4a6a40d31bb365b41a1667497b8a0a8e) nor its W1 form (prompt md5 fd372e1e2039a84d12c0de1b730f149f), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book mbal: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book mbal refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Run material balance on the Ekene survey history and read the tank: the underground withdrawal and the total expansion at the last survey, the oil in place the Havlena-Odeh straight line gives, the share of that expansion carried by rock and connate water, the depletion drive index, and the oil expansion Eo at the last survey.',
           fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb
     where app_slug = 'mbal' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book mbal refused: mbal/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'a2b66f64989dd5f799aea0c2173f067c' and fields = '[{"key": "f_last_rb", "tol": 50, "unit": "rb", "label": "Underground withdrawal F at the last survey", "expected": 317926.842484584}, {"key": "et_last_rb", "tol": 0.00005, "unit": "rb/stb", "label": "Total expansion Et at the last survey", "expected": 0.0261900809071921}, {"key": "ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP from the Havlena-Odeh slope", "expected": 12139208.1074968}, {"key": "efw_share_pct", "tol": 0.2, "unit": "%", "label": "Efw share of Et at the last survey", "expected": 39.2996108949418}, {"key": "ddi_final", "tol": 0.005, "unit": "-", "label": "Depletion drive index at the last survey", "expected": 0.607003891050583}, {"key": "eo_last_rb_stb", "tol": 5e-05, "unit": "rb/stb", "label": "Oil expansion Eo at the last survey", "expected": 0.01589748101759514}]'::jsonb) from public.academy_capstones where app_slug = 'mbal' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book mbal refused: mbal/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Work the Fetkovich aquifer of Ahmed Example 10-10 from its published geometry: the encroachable water, the productivity index on the pseudo-steady-state form, the decay term over one annual step, and the cumulative influx after four steps. Then test the opposite error by handing a pot aquifer to the Ekene tank, which has none, and report what the regression does with the freedom.',
           fields = '[{"key": "wei_bbl", "tol": 500000, "unit": "bbl", "label": "Fetkovich Wei for Ahmed 10-10", "expected": 211934253.721285}, {"key": "j_bbl_d_psi", "tol": 0.5, "unit": "bbl/d/psi", "label": "Aquifer productivity index J", "expected": 116.496154838747}, {"key": "decay_365", "tol": 0.002, "unit": "-", "label": "Decay term over one 365 day step", "expected": 0.422897624804177}, {"key": "we_final_mmbbl", "tol": 0.4, "unit": "MMbbl", "label": "Cumulative We after four steps", "expected": 37.9731544101719}, {"key": "pot_ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP when a pot aquifer is forced on Ekene", "expected": -516449.043355256}, {"key": "pot_r2", "tol": 0.0001, "unit": "-", "label": "R-squared of that wrong-model fit", "expected": 0.999485673716372}]'::jsonb
     where app_slug = 'mbal' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book mbal refused: mbal/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '18a6332ea1f24ba62671247be2020252' and fields = '[{"key": "wei_bbl", "tol": 500000, "unit": "bbl", "label": "Fetkovich Wei for Ahmed 10-10", "expected": 211934253.721285}, {"key": "j_bbl_d_psi", "tol": 0.5, "unit": "bbl/d/psi", "label": "Aquifer productivity index J", "expected": 116.496154838747}, {"key": "decay_365", "tol": 0.002, "unit": "-", "label": "Decay term over one 365 day step", "expected": 0.422897624804177}, {"key": "we_final_mmbbl", "tol": 0.4, "unit": "MMbbl", "label": "Cumulative We after four steps", "expected": 37.9731544101719}, {"key": "pot_ooip_stb", "tol": 20000, "unit": "stb", "label": "OOIP when a pot aquifer is forced on Ekene", "expected": -516449.043355256}, {"key": "pot_r2", "tol": 0.0001, "unit": "-", "label": "R-squared of that wrong-model fit", "expected": 0.999485673716372}]'::jsonb) from public.academy_capstones where app_slug = 'mbal' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book mbal refused: mbal/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Run Carter-Tracy with a finite aquifer on Dake Exercise 9.2 and report the oil in place and the cumulative influx the engine recovers, together with the bounded-circle dimensionless pressure at a dimensionless time of 100. Then work the combination-drive terms of Ahmed Example 11-1: the water influx, the water drive index, and the depletion drive index, each under the convention that actually closes.',
           fields = '[{"key": "dake_ooip_mmstb", "tol": 3, "unit": "MMSTB", "label": "Dake 9.2 OOIP from Carter-Tracy", "expected": 307.221409553720}, {"key": "dake_we_mmrb", "tol": 1, "unit": "MMrb", "label": "Dake 9.2 cumulative water influx", "expected": 88.0645883139400}, {"key": "pd_finite_100", "tol": 0.05, "unit": "-", "label": "Bounded-circle pD at reD 5, tD 100", "expected": 9.30886079703705}, {"key": "a111_we_bbl", "tol": 500, "unit": "bbl", "label": "Ahmed 11-1 water influx We", "expected": 411281.250000001}, {"key": "a111_wdi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 water drive index", "expected": 0.211250877090399}, {"key": "a111_ddi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 depletion drive index, net convention", "expected": 0.43854519939188374}]'::jsonb
     where app_slug = 'mbal' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book mbal refused: mbal/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'fd372e1e2039a84d12c0de1b730f149f' and fields = '[{"key": "dake_ooip_mmstb", "tol": 3, "unit": "MMSTB", "label": "Dake 9.2 OOIP from Carter-Tracy", "expected": 307.221409553720}, {"key": "dake_we_mmrb", "tol": 1, "unit": "MMrb", "label": "Dake 9.2 cumulative water influx", "expected": 88.0645883139400}, {"key": "pd_finite_100", "tol": 0.05, "unit": "-", "label": "Bounded-circle pD at reD 5, tD 100", "expected": 9.30886079703705}, {"key": "a111_we_bbl", "tol": 500, "unit": "bbl", "label": "Ahmed 11-1 water influx We", "expected": 411281.250000001}, {"key": "a111_wdi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 water drive index", "expected": 0.211250877090399}, {"key": "a111_ddi", "tol": 0.002, "unit": "-", "label": "Ahmed 11-1 depletion drive index, net convention", "expected": 0.43854519939188374}]'::jsonb) from public.academy_capstones where app_slug = 'mbal' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book mbal refused: mbal/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book mbal: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
